import numpy as np
from itertools import combinations_with_replacement
# NARMA10 and NARMA2: the baseline ladder (mean, linear lags, quadratic lags, ESNs of three sizes).
# Lags 0..L-1 of u. The NARMA10 target at step k uses u at lags 1 and 10, so it needs L = 11.
def narma10(u):
    y = np.zeros_like(u)
    for t in range(9, len(u) - 1):
        y[t + 1] = 0.3 * y[t] + 0.05 * y[t] * y[t - 9:t + 1].sum() + 1.5 * u[t - 9] * u[t] + 0.1
    return y
def narma2(u):
    y = np.zeros_like(u)
    for t in range(2, len(u)):
        y[t] = 0.4 * y[t - 1] + 0.4 * y[t - 1] * y[t - 2] + 0.6 * u[t - 1] ** 3 + 0.1
    return y
def esn(u, N, seed=1, radius=0.9, in_scale=0.5):
    r = np.random.default_rng(seed)
    W = r.normal(size=(N, N)); W *= radius / max(abs(np.linalg.eigvals(W)))
    w_in = r.uniform(-in_scale, in_scale, N); x = np.zeros(N); X = np.zeros((len(u), N))
    for t, ut in enumerate(u): x = np.tanh(W @ x + w_in * ut); X[t] = x
    return X
def nmse(F, y, wash=200, ntr=3000, lam=1e-8):
    A = np.hstack([F, np.ones((len(F), 1))])
    w = np.linalg.solve(A[wash:ntr].T @ A[wash:ntr] + lam * np.eye(A.shape[1]), A[wash:ntr].T @ y[wash:ntr])
    return np.mean((A[ntr:] @ w - y[ntr:]) ** 2) / np.var(y[ntr:])
def lags(u, L): return np.stack([np.roll(u, k) for k in range(L)], 1)
def quad(F):
    cols = [F[:, i] * F[:, j] for i, j in combinations_with_replacement(range(F.shape[1]), 2)]
    return np.hstack([F, np.stack(cols, 1)])
u = np.random.default_rng(0).uniform(0, 0.5, 4000)
for name, y, L in (("NARMA10", narma10(u), 11), ("NARMA2", narma2(u), 3)):
    print(f"{name}: target mean {y.mean():.3f}, std {y.std():.3f}, range {y.min():.3f} to {y.max():.3f}")
    print(f"   predict the training mean:        NMSE = {np.mean((y[3000:] - y[200:3000].mean())**2) / np.var(y[3000:]):.3f}")
    print(f"   linear on {L} lags:                 NMSE = {nmse(lags(u, L), y):.3f}")
    print(f"   quadratic on {L} lags ({L + L*(L+1)//2} features): NMSE = {nmse(quad(lags(u, L)), y):.3f}")
    if name == "NARMA10":
        print(f"   quadratic on 20 lags (230 features): NMSE = {nmse(quad(lags(u, 20)), y):.3f}")
    for N in (25, 50, 200): print(f"   ESN with {N:3d} units:              NMSE = {nmse(esn(u, N), y):.3f}")
bad = 0
for seed in range(200):
    y = narma10(np.random.default_rng(seed).uniform(0, 0.5, 1000))
    bad += (not np.all(np.isfinite(y))) or np.abs(y).max() > 5
print("NARMA10 runs that blew up, out of 200 random input draws:", bad)
